#!/usr/bin/env python3
"""Port selected pstack skills (MIT, github.com/michael-denyer/pstack-claude) to OpenCode.

    python3 vendor/pstack-sync.py            # clone/update vendor/pstack, regenerate
    python3 vendor/pstack-sync.py --offline  # regenerate from the existing checkout

Writes:
  skills/<name>/                 ported skills (Claude/Codex/Muse plumbing stripped,
                                 Agent/subagent_type calls mapped to OpenCode's subagent tool)
  skills/engineering-principles/ the 30 principle-* skills as one indexed skill
                                 (one catalog entry instead of 30)
  agents/{thermo-review,thermo-quality-review,comment-sicko}.md
                                 read-only reviewer subagents (sandbox copied from code-reviewer.md)
Re-run after updating upstream; hand edits to generated files are overwritten.
"""
from __future__ import annotations

import os
import re
import shutil
import subprocess
import sys

CFG = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
SRC = os.path.join(CFG, "vendor", "pstack")
REPO = "https://github.com/michael-denyer/pstack-claude"
SKILLS = ["thermo-nuclear-code-quality-review", "thermo-nuclear-review", "thermos", "deslop",
          "no-comments", "blast-radius", "correct", "benchmark-checklist",
          "typescript-best-practices", "sharpen"]
AGENTS = {  # upstream agent -> OpenCode subagent name
    "thermo-nuclear-review-subagent": "thermo-review",
    "thermo-nuclear-code-quality-review-subagent": "thermo-quality-review",
    "comment-sicko": "comment-sicko",
}
STAMP = "<!-- Generated by vendor/pstack-sync.py from pstack (MIT, (c) Lauren Tan, Michael Denyer, Cursor). Do not edit. -->"


def sh(*args: str) -> None:
    subprocess.run(args, check=True, stdout=subprocess.DEVNULL)


def fetch() -> None:
    if os.path.isdir(os.path.join(SRC, ".git")):
        sh("git", "-C", SRC, "pull", "-q", "--ff-only")
    else:
        sh("git", "clone", "-q", "--depth", "1", REPO, SRC)


def drop_section(text: str, title: str) -> str:
    return re.sub(rf"(?ms)^## {re.escape(title)}\n.*?(?=^## |\Z)", "", text)


def port(text: str) -> str:
    text = re.sub(r"(?m)^On (Codex|GitHub Copilot|Muse|Antigravity), read the \[platform mapping\].*\n\n?", "", text)
    for sec in ("Models", "Reasoning effort"):
        text = drop_section(text, sec)
    for up, oc in AGENTS.items():
        text = text.replace(f'`subagent_type: "pstack:{up}"`', f"the `{oc}` subagent")
        text = text.replace(f'subagent_type: "pstack:{up}"', f"the `{oc}` subagent")
    text = text.replace("with `run_in_background: true`", "(two `subagent` calls in one message, so they run in parallel)")
    text = text.replace("Spawn `Agent` with", "Call the `subagent` tool with")
    text = re.sub(r"`Agent` (tool|subagent)", r"`subagent` \1", text)
    # pstack model-sheet plumbing has no OpenCode equivalent: subagents use their own ladder model
    text = re.sub(r"(?m)^\s*Set `model`[^\n]*\n(\s*\n)?", "", text)
    text = re.sub(r"(?m)^[^\n]*pstack-models\.md[^\n]*\n", "", text)
    text = re.sub(r" ?Pick each subagent's reasoning level for the job, per the Subagents section of the \*\*poteto-mode\*\* skill\.", "", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    # stamp after the frontmatter
    m = re.match(r"(?s)^(---\n.*?\n---\n)(.*)$", text)
    return f"{m.group(1)}\n{STAMP}\n{m.group(2).lstrip()}" if m else f"{STAMP}\n{text}"


def port_skill(name: str) -> None:
    src = os.path.join(SRC, "plugins", "pstack", "skills", name)
    dst = os.path.join(CFG, "skills", name)
    if os.path.lexists(dst):
        shutil.rmtree(dst)
    shutil.copytree(src, dst)
    p = os.path.join(dst, "SKILL.md")
    with open(p) as f:
        body = port(f.read())
    with open(p, "w") as f:
        f.write(body)


def principles() -> None:
    root = os.path.join(SRC, "plugins", "pstack", "skills")
    dst = os.path.join(CFG, "skills", "engineering-principles")
    if os.path.exists(dst):
        shutil.rmtree(dst)
    os.makedirs(os.path.join(dst, "references"))
    rows = []
    for name in sorted(n for n in os.listdir(root) if n.startswith("principle-")):
        with open(os.path.join(root, name, "SKILL.md")) as f:
            text = f.read()
        desc = re.search(r"(?m)^description:\s*\"?(.*?)\"?\s*$", text)
        short = name.removeprefix("principle-")
        with open(os.path.join(dst, "references", f"{short}.md"), "w") as f:
            f.write(port(text))
        rows.append(f"- **{short}** — {desc.group(1) if desc else ''} → `references/{short}.md`")
    with open(os.path.join(dst, "SKILL.md"), "w") as f:
        f.write("---\nname: engineering-principles\n"
                "description: \"Engineering principles for clean, debloated code: subtract before you add, fix root causes, "
                "prove it works, boundary discipline, minimize reader load, type-system discipline, idempotency, and more. "
                "Use when designing, refactoring, debugging, reviewing, or deciding how much code a change deserves.\"\n---\n\n"
                f"{STAMP}\n\n# Engineering principles\n\n"
                "Pick the principles whose trigger matches the situation and read only those reference files. "
                "Each is short; apply it, do not quote it.\n\n" + "\n".join(rows) + "\n")


AGENT_TEMPLATE = "code-reviewer.md"


def agents() -> None:
    with open(os.path.join(CFG, "agents", AGENT_TEMPLATE)) as f:
        tmpl = f.read()
    perms = re.search(r"(?ms)^permissions:\n.*?(?=^---$)", tmpl).group(0)
    model = re.search(r"(?m)^model:.*$", tmpl).group(0)
    for up, oc in AGENTS.items():
        with open(os.path.join(SRC, "plugins", "pstack", "agents", f"{up}.md")) as f:
            text = f.read()
        fm = re.match(r"(?s)^---\n(.*?)\n---\n(.*)$", text)
        desc = re.search(r"(?m)^description:\s*(.*)$", fm.group(1)).group(1).strip().strip('"')
        desc = desc.replace("Invoked through the `Agent` tool", "Invoked through the subagent tool").replace(" in this plugin", "")
        body = port(fm.group(2))
        for u, o in AGENTS.items():
            body = body.replace(f"pstack:{u}", o)
        body = body.replace(STAMP + "\n", "").replace("an **`subagent` subagent**", "a **subagent**").replace("through the `Explore` agent", "through the `explorer` subagent")
        body = body.replace("(shipped in this plugin)", "(installed as an OpenCode skill)").replace("in this plugin", "in OpenCode's skills")
        with open(os.path.join(CFG, "agents", f"{oc}.md"), "w") as f:
            f.write(f"---\ndescription: \"{desc}\"\nmode: subagent\n{model}\n{perms}---\n\n{STAMP}\n{body.lstrip()}")


def main() -> int:
    if "--offline" not in sys.argv:
        fetch()
    for s in SKILLS:
        port_skill(s)
    principles()
    agents()
    print(f"ported {len(SKILLS)} skills + engineering-principles + {len(AGENTS)} agents from {SRC}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
